{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "Starting July 1, 2025, the bill would require participating students to take state assessments that are given to public school students in the same grade or course. A student’s parent would be responsible for ensuring the student takes the tests.",
      "rationale": "Conveys parental responsibility and grade-or-course matching, but does not specify annual administration of all TCAP tests or state-board-authorized successors. The exemption is covered separately."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "A student’s parent would be responsible for ensuring the student takes the tests. Students in grade 11 would also take the examination given to public school students in that grade.",
      "rationale": "Conveys parental responsibility for the same examination given to public school eleventh graders. The subsequent exemption applies to these requirements."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "A student’s parent would be responsible for ensuring the student takes the tests. Students in grade 11 would also take the examination given to public school students in that grade. Students in kindergarten through grade 3 would take each of three state-approved universal reading screeners during each of the three annual testing windows.",
      "rationale": "Conveys parental responsibility, the K–3 scope, approved screeners, and each of the three annual windows. The summary separately states the alternate-assessment exemption."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Test results must be reported to the student’s parent.",
      "rationale": "Directly states the required reporting of results to the parent."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "Students whose IEP determines they would have taken the alternate assessment are exempt from these requirements.",
      "rationale": "Conveys the exemption and its controlling IEP-based alternate-assessment criterion."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "Participating schools would have to post on their websites lesson plans and syllabuses for each class, a current list of library materials, and the academic standards for each class.",
      "rationale": "Includes the responsible schools, website publication, every required category, class-level scope, and currency of the library list."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "The bill defines a library collection as materials made available to students, including course materials, and broadly lists covered materials, from books and films to applications and subscription content.",
      "rationale": "Fully conveys the library-collection definition but gives only examples of the defined materials, omitting express coverage of such categories as video games, periodicals, manuscripts, and subscription content in any form."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "It would also require participating schools to ensure all their educators hold a valid public-school teaching license issued by the state board of education.",
      "rationale": "Conveys the school’s duty, all-educator scope, license validity, public-school qualification, and issuing authority."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "Participating schools would have to post on their websites lesson plans and syllabuses for each class, a current list of library materials, and the academic standards for each class. The bill defines a library collection as materials made available to students, including course materials, and broadly lists covered materials, from books and films to applications and subscription content. It would also require participating schools to ensure all their educators hold a valid public-school teaching license issued by the state board of education. The bill adds school-posting and educator-licensing requirements to the provisions cited in Section 3 as well.",
      "rationale": "States all required publication components and expressly extends the posting requirement to Section 3."
    },
    {
      "proposition_id": "P10",
      "status": "partial",
      "summary_quote": "The bill defines a library collection as materials made available to students, including course materials, and broadly lists covered materials, from books and films to applications and subscription content.",
      "rationale": "The general definition covers student-accessible and course materials, but the examples do not convey the full express materials definition, including video games and subscription content in any form."
    },
    {
      "proposition_id": "P11",
      "status": "full",
      "summary_quote": "It would also require participating schools to ensure all their educators hold a valid public-school teaching license issued by the state board of education. The bill adds school-posting and educator-licensing requirements to the provisions cited in Section 3 as well.",
      "rationale": "States the complete licensing requirement and expressly applies it to Section 3."
    },
    {
      "proposition_id": "P12",
      "status": "partial",
      "summary_quote": "Starting July 1, 2025, the bill would require participating students to take state assessments that are given to public school students in the same grade or course. A student’s parent would be responsible for ensuring the student takes the tests. Students in grade 11 would also take the examination given to public school students in that grade. Students in kindergarten through grade 3 would take each of three state-approved universal reading screeners during each of the three annual testing windows. Test results must be reported to the student’s parent. Students whose IEP determines they would have taken the alternate assessment are exempt from these requirements. For participation in the program addressed in Section 4, taking these assessments would be a condition of participation.",
      "rationale": "Conveys grade-or-course matching and the Section 4 participation condition, but omits annual TCAP administration and the state-board-authorized successor-test alternative."
    },
    {
      "proposition_id": "P13",
      "status": "full",
      "summary_quote": "Students in grade 11 would also take the examination given to public school students in that grade. Students in kindergarten through grade 3 would take each of three state-approved universal reading screeners during each of the three annual testing windows. Test results must be reported to the student’s parent. Students whose IEP determines they would have taken the alternate assessment are exempt from these requirements. For participation in the program addressed in Section 4, taking these assessments would be a condition of participation.",
      "rationale": "Identifies the same examination given to public school eleventh graders and expressly makes taking it a Section 4 participation condition."
    },
    {
      "proposition_id": "P14",
      "status": "full",
      "summary_quote": "Students in kindergarten through grade 3 would take each of three state-approved universal reading screeners during each of the three annual testing windows. Test results must be reported to the student’s parent. Students whose IEP determines they would have taken the alternate assessment are exempt from these requirements. For participation in the program addressed in Section 4, taking these assessments would be a condition of participation.",
      "rationale": "Conveys the K–3 scope, approved screeners, each of the three annual windows, and the Section 4 participation condition."
    },
    {
      "proposition_id": "P15",
      "status": "full",
      "summary_quote": "Starting July 1, 2025,",
      "rationale": "States the act’s effective date."
    }
  ]
}
